-- Migration 469: AA-1171 (S287, alerts catalogue P0; tech lead decisions D3 and D5 of the S287 alerting decision page,
-- root docs/audits/2026-11-21-S287-alerting-inventory/README.md section 8) — the CIS in-app check thresholds as
-- settings, and a topic per alert recipient.
--
-- Why. (1) The thresholds of the CIS in-app ops checks (shared/ops_checks.py, run by the api's ops metrics sampler)
-- were code constants (JOBS_STARVED_AFTER_S = 900, ROLE_CONNECTIONS_PCT = 80, XID_AGE_LIMIT = 1e9, SPEND_NEAR_RATIO =
-- 0.8, the 2 x overdue factor, the 30-minute recompute lag, the 20 % stale research share, the 6-hour bell window;
-- the quality funnel's 20-request floor, 10 % drift share and 1 % new-model share and the 5 % cut share it shares with
-- the route_cut alert; the 1 / 24 / 20-hour bell windows of the route, day-scale and nightly checks),
-- against the house rule that every threshold is editable on an admin page (tech lead S278 / S279). D3: they move into
-- the settings registry now (maker-checker, audited), with today's values as the seeded defaults. (2) D5 adds a second
-- SNS topic for page severity (AA-CIS-Infra alert_severity.tf); its recipients are managed on the same admin page as
-- the alerts topic (Platform > Alerts > Recipients, AA-913), so each recipient row names its topic.
--
-- What:
--   1. Fifteen rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py
--      into shared/settings/compiled_defaults.json in this PR), new area "ops", scope platform, maker-checker, no
--      evidence, no env override, enforced (shared/ops_thresholds.py names the keys in this PR, the settings-lint
--      reader check; the code PR reads them):
--        cis.ops.jobs_starved_after_s       int seconds 120-7200, default 900
--        cis.ops.jobs_overdue_factor        numeric 1.2-10, default 2
--        cis.ops.role_connections_pct       pct 50-99, default 80
--        cis.ops.xid_age_limit              int 1e8-1.5e9, default 1e9
--        cis.ops.recompute_lag_limit_s      int seconds 600-86400, default 1800
--        cis.ops.research_stale_share_pct   pct 1-100, default 20
--        cis.ops.app_spend_near_pct         pct 50-99, default 80
--        cis.ops.bell_every_hours           int hours 1-48, default 6
--        cis.ops.reply_cut_alert_pct        numeric % 1-50, default 5 (route_cut and qf_cut)
--        cis.ops.qf_min_requests            int requests 5-1000, default 20
--        cis.ops.qf_drift_alert_pct         numeric % 1-100, default 10
--        cis.ops.qf_drift_new_model_pct     numeric % 0.1-20, default 1
--        cis.ops.bell_every_route_hours     int hours 1-24, default 1 (route_fb, route_last)
--        cis.ops.bell_every_daily_hours     int hours 1-168, default 24 (stage coverage, route_cost, route_cut)
--        cis.ops.bell_every_nightly_hours   int hours 12-23, default 20 (research checks, route digest, qf_*)
--      The bell window of route_back (the primary model is back, 1 minute) stays a technical constant: the route
--      watch raises it once per recovery, the window only folds two raises of the same tick.
--      Each seed row carries its plain label and its EN + VI operator guide (CIS 416 rule).
--   2. shared.alert_recipient.topic text NOT NULL DEFAULT 'alerts', CHECK alerts | page (alerts = the alerts topic,
--      every alert; page = the page topic, page-severity alerts only). The active-address unique index becomes
--      (topic, email): one address may be on both topics. Existing rows are 'alerts' (the default; they were all on the
--      alerts topic).
--   3. Register 469.
--
-- Behaviour on apply. None for running code: no setting value row is seeded and the code on main reads neither the
-- keys nor the column; its INSERT omits topic (default 'alerts') and its duplicate check by e-mail stays stricter than
-- the new index. After the code PR the checks read the defaults (today's values) until an administrator changes them.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table
-- and an ALTER of an existing table. MIG-4: a migration-only PR, applied on Dev by Infra Migration Apply when the job
-- tables are idle (ADR 0017a), then the code PR (readiness requires 469: the recipients page reads the column).
-- DM-6.1: no personal data added (the e-mail column is unchanged). DM-7.1: no new table.
--
-- Number. Owner main max (465) + 1, with 466-468 reserved by other S287 lanes. If the owner main max + 1 differs at
-- merge, renumber (git grep '469_' and '469' here, in tests/integration/test_aa1171_migration_469.py,
-- compiled_defaults.json, shared/ops_thresholds.py and docs/implementation-notes/AA-1171.md).
--
-- Locks. One INSERT of fifteen rows; ADD COLUMN with a constant default (catalog only, PG 11+), ADD CONSTRAINT CHECK on a
-- table of a handful of rows, one CREATE UNIQUE INDEX and one DROP INDEX on that table. lock_timeout 5s.
--
-- Rollback (a new forward migration, after the code PR is reverted): DELETE the keys' value rows first, then the keys;
-- DELETE the topic = 'page' recipient rows (unsubscribe them on the page first), recreate the (email) index, drop the
-- (topic, email) index, the CHECK and the column.

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.ops.jobs_starved_after_s", "app": "cis", "area": "ops", "label": "Ops check: job queue starved after (seconds)", "description": "The in-app check jobs_starved (shared/ops_checks.py, run by the api's ops metrics sampler every 5 minutes) alerts the admin bell and the alerts topic when the oldest due shared.job row that no free worker slot claims has waited longer than this. It replaced the CloudWatch alarm aa-cis-<env>-jobs-queue-age (S263); 900 s was that alarm's value.", "value_type": "int", "unit": "seconds", "min_value": 120, "max_value": 7200, "allowed_values": null, "default_value": 900, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How long a due job may wait for a worker before the job queue alert fires.", "raise": "The alert fires later: a stopped worker or an unclaimed job kind is noticed later.", "lower": "The alert fires sooner, also on short waits behind a busy worker (more noise).", "when": "Raise it only when long but normal waits (a wave filling every slot) alert; lower it when jobs must start fast.", "example": "With the default 900 s, a job due at 10:00 that no worker took by 10:15 raises one alert."}, "vi": {"what": "Một job đến hạn được chờ worker bao lâu trước khi cảnh báo hàng đợi job bật.", "raise": "Cảnh báo bật muộn hơn: worker dừng hay một loại job không ai nhận bị phát hiện muộn hơn.", "lower": "Cảnh báo bật sớm hơn, kể cả khi chỉ chờ ngắn sau một worker đang bận (nhiều cảnh báo thừa hơn).", "when": "Chỉ tăng khi những lần chờ dài nhưng bình thường (một wave chiếm hết slot) gây cảnh báo; giảm khi job phải chạy nhanh.", "example": "Với mặc định 900 giây, một job đến hạn lúc 10:00 mà tới 10:15 chưa worker nào nhận thì bật một cảnh báo."}}},
{"key": "cis.ops.jobs_overdue_factor", "app": "cis", "area": "ops", "label": "Ops check: running job overdue after (x expected time)", "description": "A running shared.job attempt counts as overdue once it has run longer than this many times its kind's expected seconds (shared/jobs/backlog.py). The in-app check jobs_overdue alerts on any overdue running job, and the Jobs page marks it. 2 was the value of the S263 code and of the CloudWatch alarm it replaced.", "value_type": "numeric", "unit": "x expected", "min_value": 1.2, "max_value": 10, "allowed_values": null, "default_value": 2, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many times its expected time a running job may take before it counts as overdue.", "raise": "Slow but healthy jobs stop alerting; a job that hangs holds its worker slot longer before anyone hears of it.", "lower": "A hung job is reported sooner, but jobs that are only slow (a large tour, a slow provider) alert too.", "when": "Raise it when slow but finishing jobs alert often; lower it when a hung job must be caught quickly.", "example": "With the default 2, a job kind expected to take 10 minutes is overdue after 20 minutes of running."}, "vi": {"what": "Một job đang chạy được phép chạy gấp bao nhiêu lần thời gian dự kiến trước khi bị coi là quá hạn.", "raise": "Job chậm nhưng vẫn khoẻ không còn gây cảnh báo; job bị treo giữ slot worker lâu hơn trước khi có người biết.", "lower": "Job bị treo được báo sớm hơn, nhưng job chỉ chậm (tour lớn, nhà cung cấp chậm) cũng gây cảnh báo.", "when": "Tăng khi job chậm nhưng vẫn xong thường xuyên gây cảnh báo; giảm khi cần bắt job treo thật nhanh.", "example": "Với mặc định 2, một loại job dự kiến chạy 10 phút bị coi là quá hạn sau 20 phút."}}},
{"key": "cis.ops.role_connections_pct", "app": "cis", "area": "ops", "label": "Ops check: database role connections alert (%)", "description": "The in-app check rds_role_connections alerts when a LOGIN role of the shared database holds more than this share of its CONNECTION LIMIT (pg_roles, read by the api's ops sampler). New connections of that role fail at the limit. It replaced the six CloudWatch alarms aa-cis-<env>-rds-role-connections-* (S263); 80 % was their value.", "value_type": "pct", "unit": "%", "min_value": 50, "max_value": 99, "allowed_values": null, "default_value": 80, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How full a database login role's connection limit may get before an alert.", "raise": "Less warning before an app runs out of connections and its requests start failing.", "lower": "Earlier warning, but busy normal periods (a wave, a deploy with two task sets) may alert.", "when": "Lower it when a role has hit its limit without warning; raise it when normal peaks alert.", "example": "With the default 80 %, a role with a limit of 20 alerts at 17 open connections."}, "vi": {"what": "Giới hạn kết nối của một role đăng nhập database được đầy tới mức nào trước khi cảnh báo.", "raise": "Ít thời gian báo trước hơn khi một app sắp hết kết nối và request bắt đầu lỗi.", "lower": "Báo sớm hơn, nhưng các lúc bận bình thường (một wave, deploy có hai bộ task) có thể gây cảnh báo.", "when": "Giảm khi một role đã chạm giới hạn mà không có cảnh báo; tăng khi các đỉnh bình thường gây cảnh báo.", "example": "Với mặc định 80 %, một role có giới hạn 20 kết nối sẽ cảnh báo khi mở 17 kết nối."}}},
{"key": "cis.ops.xid_age_limit", "app": "cis", "area": "ops", "label": "Ops check: database transaction ID age alert", "description": "The in-app check rds_xid_age alerts when max(age(datfrozenxid)) of the shared database is above this (autovacuum is not freezing a table; wraparound guard). PostgreSQL stops accepting writes near 2,000,000,000. It replaced the CloudWatch alarm aa-cis-<env>-rds-max-used-xid-high (S263); 1,000,000,000 was its value.", "value_type": "int", "unit": "transactions", "min_value": 100000000, "max_value": 1500000000, "allowed_values": null, "default_value": 1000000000, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How old the oldest unfrozen transaction ID of the database may get before an alert.", "raise": "Less time to fix autovacuum before PostgreSQL protects itself by refusing writes.", "lower": "Earlier warning; on a database that is simply busy the alert may fire while autovacuum would catch up by itself.", "when": "Keep the default unless the database team asks; lower it if autovacuum was found lagging before.", "example": "With the default 1,000,000,000 the alert leaves about half of the safe range to act."}, "vi": {"what": "ID giao dịch cũ nhất chưa được đóng băng của database được cũ tới mức nào trước khi cảnh báo.", "raise": "Ít thời gian sửa autovacuum hơn trước khi PostgreSQL tự bảo vệ bằng cách từ chối ghi.", "lower": "Báo sớm hơn; với database chỉ đang bận, cảnh báo có thể bật dù autovacuum tự đuổi kịp.", "when": "Giữ mặc định trừ khi người phụ trách database yêu cầu; giảm nếu trước đây autovacuum từng bị chậm.", "example": "Với mặc định 1.000.000.000, cảnh báo còn chừa khoảng một nửa vùng an toàn để xử lý."}}},
{"key": "cis.ops.recompute_lag_limit_s", "app": "cis", "area": "ops", "label": "Ops check: tour on/off change not recomputed after (seconds)", "description": "The in-app check recompute_lifecycle_lag alerts when a tour was retired, paused or restored longer ago than this and no Score and Route recompute has finished since (services/recompute/lifecycle.py). 1800 s = the 20-minute debounce cap plus a slow run.", "value_type": "int", "unit": "seconds", "min_value": 600, "max_value": 86400, "allowed_values": null, "default_value": 1800, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How long a tour switched on or off may wait for Score and Route to catch up before an alert.", "raise": "Tenants may see a retired tour, or miss a restored one, for longer before anyone hears of it.", "lower": "Alerts sooner, but a normal debounced recompute that runs a little late may alert too.", "when": "Raise it while recomputes are known to be slow (a large catalogue change); lower it when tenants must see changes quickly.", "example": "With the default 1800 s, a tour retired at 09:00 with no recompute finished by 09:30 raises one alert."}, "vi": {"what": "Một tour vừa bật hoặc tắt được chờ Score và Route cập nhật bao lâu trước khi cảnh báo.", "raise": "Đại lý có thể thấy tour đã ngừng, hoặc không thấy tour vừa mở lại, lâu hơn trước khi có người biết.", "lower": "Cảnh báo sớm hơn, nhưng một lượt tính lại bình thường chạy hơi trễ cũng có thể gây cảnh báo.", "when": "Tăng khi biết các lượt tính lại đang chậm (thay đổi lớn cả catalogue); giảm khi đại lý cần thấy thay đổi nhanh.", "example": "Với mặc định 1800 giây, tour ngừng lúc 09:00 mà tới 09:30 chưa có lượt tính lại nào xong thì bật một cảnh báo."}}},
{"key": "cis.ops.research_stale_share_pct", "app": "cis", "area": "ops", "label": "Ops check: search demand research stale share alert (%)", "description": "The in-app check research_stale_share (once a day) alerts when more than this share of the places research covers in a market an active tenant targets has no search demand research or research older than 365 days (services/acp_contract/research_coverage.py). The Data coverage page marks the same markets as gaps.", "value_type": "pct", "unit": "%", "min_value": 1, "max_value": 100, "allowed_values": null, "default_value": 20, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "What share of a market's places may lack fresh search demand research before an alert.", "raise": "Fewer alerts; more places score with no demand signal before anyone is told.", "lower": "Alerts sooner, which may ask for paid research runs more often.", "when": "Lower it when content in a market is scored without demand too often; raise it while research spend is on hold.", "example": "With the default 20 %, a market of 50 places alerts when 11 of them have no fresh research."}, "vi": {"what": "Tỷ lệ địa điểm của một thị trường thiếu nghiên cứu nhu cầu tìm kiếm còn mới được phép tới đâu trước khi cảnh báo.", "raise": "Ít cảnh báo hơn; nhiều địa điểm bị chấm điểm không có tín hiệu nhu cầu hơn trước khi có người được báo.", "lower": "Cảnh báo sớm hơn, có thể dẫn tới phải chạy nghiên cứu trả phí thường xuyên hơn.", "when": "Giảm khi nội dung một thị trường bị chấm điểm thiếu nhu cầu quá thường xuyên; tăng khi đang tạm dừng chi cho nghiên cứu.", "example": "Với mặc định 20 %, thị trường có 50 địa điểm sẽ cảnh báo khi 11 địa điểm không có nghiên cứu mới."}}},
{"key": "cis.ops.app_spend_near_pct", "app": "cis", "area": "ops", "label": "Ops check: app AI spend near its daily cap (%)", "description": "The in-app check llm_spend_alert.<app>.near alerts when an app's AI spend today (UTC) passes this share of its daily budget (app profile default_daily_budget_usd; today TripPlanner). The cap alert at 100 % is separate. 80 % is TripPlanner's own warning share.", "value_type": "pct", "unit": "%", "min_value": 50, "max_value": 99, "allowed_values": null, "default_value": 80, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "At what share of an app's daily AI budget the 'near its cap' alert fires.", "raise": "The warning comes later, leaving less of the day to react before the app stops calling models.", "lower": "The warning comes earlier, also on days that would have stayed under the cap.", "when": "Lower it when the cap was reached with little warning; raise it when busy normal days alert.", "example": "With the default 80 % and a 5 USD daily budget, the alert fires at 4 USD of spend."}, "vi": {"what": "Ở mức bao nhiêu phần trăm ngân sách AI hằng ngày của một app thì cảnh báo 'sắp chạm trần' bật.", "raise": "Cảnh báo tới muộn hơn, còn ít thời gian trong ngày để xử lý trước khi app ngừng gọi model.", "lower": "Cảnh báo tới sớm hơn, kể cả những ngày lẽ ra vẫn dưới trần.", "when": "Giảm khi app chạm trần mà gần như không được báo trước; tăng khi những ngày bận bình thường gây cảnh báo.", "example": "Với mặc định 80 % và ngân sách 5 USD mỗi ngày, cảnh báo bật khi đã chi 4 USD."}}},
{"key": "cis.ops.bell_every_hours", "app": "cis", "area": "ops", "label": "Ops check: repeat a firing check's bell after (hours)", "description": "A CIS in-app check that keeps firing writes at most one admin bell per this many hours (shared/ops_checks.py raise_alert; the e-mail stays at most one per check and UTC day). Checks with their own window (stage coverage, route alerts, the quality funnel digest) keep it. 6 hours was the S263 value.", "value_type": "int", "unit": "hours", "min_value": 1, "max_value": 48, "allowed_values": null, "default_value": 6, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How often the admin bell repeats a problem that is still there.", "raise": "Fewer repeated bells for a long problem; a problem still open is less visible in the bell.", "lower": "The bell repeats sooner, so a long problem fills the bell list.", "when": "Raise it when a known long problem crowds the bell; lower it while a fix is being watched closely.", "example": "With the default 6 hours, a starved job queue from 08:00 to 20:00 bells at 08:00, 14:00 and 20:00."}, "vi": {"what": "Chuông admin lặp lại một vấn đề vẫn còn đó sau bao lâu.", "raise": "Ít chuông lặp lại hơn với vấn đề kéo dài; vấn đề còn mở khó thấy hơn trong chuông.", "lower": "Chuông lặp lại sớm hơn, nên vấn đề kéo dài làm đầy danh sách chuông.", "when": "Tăng khi một vấn đề đã biết kéo dài chiếm chỗ trong chuông; giảm khi đang theo dõi sát một bản sửa.", "example": "Với mặc định 6 giờ, hàng đợi job bị kẹt từ 08:00 tới 20:00 sẽ rung chuông lúc 08:00, 14:00 và 20:00."}}},
{"key": "cis.ops.reply_cut_alert_pct", "app": "cis", "area": "ops", "label": "Ops check: replies cut at their token ceiling alert (%)", "description": "The route alert route_cut.<stage> (llm_route_watch, last 24 hours) and the weekly quality funnel alert qf_cut.<stage> (report CIS-08, last 7 days) fire when more than this share of a stage's billed replies stopped on their output-token ceiling. Each cut reply costs a retry at double the ceiling and can leave content short. 5 % was the S271 value of both.", "value_type": "numeric", "unit": "%", "min_value": 1, "max_value": 50, "allowed_values": null, "default_value": 5, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "What share of a stage's replies may stop at their token ceiling before an alert.", "raise": "Fewer alerts; more replies are cut and retried (extra cost) before anyone is told.", "lower": "Alerts sooner, also on stages where a few long replies are normal.", "when": "Lower it when cut replies are found in content with no alert; raise it while a known long stage is being fixed.", "example": "With the default 5 %, a stage with 200 replies in the window alerts at 11 cut replies."}, "vi": {"what": "Tỷ lệ câu trả lời của một stage bị cắt ở trần token được phép tới đâu trước khi cảnh báo.", "raise": "Ít cảnh báo hơn; nhiều câu trả lời bị cắt và gọi lại (thêm chi phí) hơn trước khi có người được báo.", "lower": "Cảnh báo sớm hơn, kể cả ở các stage mà vài câu trả lời dài là bình thường.", "when": "Giảm khi thấy nội dung bị cắt mà không có cảnh báo; tăng khi đang sửa một stage đã biết là dài.", "example": "Với mặc định 5 %, một stage có 200 câu trả lời trong khung giờ sẽ cảnh báo khi có 11 câu bị cắt."}}},
{"key": "cis.ops.qf_min_requests", "app": "cis", "area": "ops", "label": "Quality funnel alert: minimum requests per week", "description": "The weekly quality funnel alerts (qf_cut, qf_fb and qf_drift per stage, report CIS-08, services/quality/funnel.py) need at least this many rows of the stage in the last 7 days (drift: also in the 7 days before). A stage's route policy min_requests above it wins. 20 was the S271 value.", "value_type": "int", "unit": "requests", "min_value": 5, "max_value": 1000, "allowed_values": null, "default_value": 20, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many requests a stage needs in a week before the quality funnel judges it.", "raise": "Quiet stages are no longer judged, so a problem on a small stage is not reported.", "lower": "Small stages are judged too; a handful of bad requests can raise an alert.", "when": "Raise it when small stages alert on a few requests; lower it when a low-volume stage matters.", "example": "With the default 20, a stage with 15 requests this week raises no funnel alert."}, "vi": {"what": "Một stage cần bao nhiêu request trong tuần thì quality funnel mới đánh giá nó.", "raise": "Các stage ít request không còn được đánh giá, nên vấn đề ở stage nhỏ không được báo.", "lower": "Stage nhỏ cũng được đánh giá; vài request lỗi có thể gây cảnh báo.", "when": "Tăng khi stage nhỏ gây cảnh báo chỉ vì vài request; giảm khi một stage ít request vẫn quan trọng.", "example": "Với mặc định 20, một stage có 15 request trong tuần không gây cảnh báo funnel nào."}}},
{"key": "cis.ops.qf_drift_alert_pct", "app": "cis", "area": "ops", "label": "Quality funnel alert: served-model drift share (%)", "description": "The weekly quality funnel alert qf_drift.<stage> (report CIS-08) fires when at least this share of the stage's answered requests in the last 7 days came from a model that served almost none of them the week before (a route, catalog or provider change). 10 % was the S271 value.", "value_type": "numeric", "unit": "%", "min_value": 1, "max_value": 100, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "What share of a stage's answers may come from a newly serving model before a drift alert.", "raise": "A model change has to carry more traffic before anyone is told it happened.", "lower": "Even a small share served by a new model alerts, also short provider failovers.", "when": "Lower it on stages gated by an eval, where any model change matters; raise it when failovers alert often.", "example": "With the default 10 %, 30 of 300 answers from a model new this week raise one alert."}, "vi": {"what": "Tỷ lệ câu trả lời của một stage đến từ một model mới bắt đầu phục vụ được phép tới đâu trước khi cảnh báo lệch model.", "raise": "Một lần đổi model phải chiếm nhiều lưu lượng hơn mới có người được báo.", "lower": "Chỉ một phần nhỏ do model mới trả lời cũng gây cảnh báo, kể cả những lần chuyển nhà cung cấp ngắn.", "when": "Giảm ở các stage có eval kiểm soát, nơi mọi thay đổi model đều quan trọng; tăng khi các lần chuyển dự phòng hay gây cảnh báo.", "example": "Với mặc định 10 %, 30 trên 300 câu trả lời đến từ một model mới trong tuần sẽ bật một cảnh báo."}}},
{"key": "cis.ops.qf_drift_new_model_pct", "app": "cis", "area": "ops", "label": "Quality funnel alert: a model counts as new below (%)", "description": "For the drift alert qf_drift.<stage> a model counts as new when it served under this share of the stage's answered requests in the 7 days before the last 7. 1 % was the S271 value.", "value_type": "numeric", "unit": "%", "min_value": 0.1, "max_value": 20, "allowed_values": null, "default_value": 1, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Below what share of last week's answers a model still counts as new to a stage.", "raise": "Models that already served a little last week still count as new, so more drift alerts.", "lower": "Only models that served almost nothing last week count as new, so fewer drift alerts.", "when": "Keep the default unless drift alerts miss a model that served a trickle before taking over.", "example": "With the default 1 %, a model with 2 of last week's 400 answers (0.5 %) counts as new."}, "vi": {"what": "Dưới tỷ lệ bao nhiêu câu trả lời của tuần trước thì một model vẫn được coi là mới với stage.", "raise": "Các model tuần trước đã phục vụ một ít vẫn bị coi là mới, nên có nhiều cảnh báo lệch hơn.", "lower": "Chỉ model gần như không phục vụ tuần trước mới bị coi là mới, nên ít cảnh báo lệch hơn.", "when": "Giữ mặc định trừ khi cảnh báo lệch bỏ sót một model trước đó đã phục vụ lác đác rồi mới chiếm phần lớn.", "example": "Với mặc định 1 %, một model có 2 trên 400 câu trả lời tuần trước (0,5 %) được coi là mới."}}},
{"key": "cis.ops.bell_every_route_hours", "app": "cis", "area": "ops", "label": "Ops check: repeat a route fallback bell after (hours)", "description": "The route alerts route_fb.<stage> (a stage served by a fallback model) and route_last.<stage> (a stage on the last model of its route) of llm_route_watch write at most one admin bell per this many hours while they keep firing. 1 hour was the S268 value.", "value_type": "int", "unit": "hours", "min_value": 1, "max_value": 24, "allowed_values": null, "default_value": 1, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How often the bell repeats a stage that is still served by a fallback or its last model.", "raise": "Fewer repeated bells during a long provider outage; a stage still degraded is less visible.", "lower": "Not below 1 hour: the route watch runs on a short tick and would bell on every run.", "when": "Raise it during a known provider outage that crowds the bell; set it back after.", "example": "With the default 1 hour, a fallback from 10:00 to 13:00 bells at 10:00, 11:00, 12:00 and 13:00."}, "vi": {"what": "Chuông lặp lại bao lâu một lần cho một stage vẫn đang dùng model dự phòng hay model cuối của route.", "raise": "Ít chuông lặp lại hơn khi nhà cung cấp gặp sự cố dài; stage còn suy giảm khó thấy hơn.", "lower": "Không dưới 1 giờ: route watch chạy theo nhịp ngắn và sẽ rung chuông mỗi lần chạy.", "when": "Tăng khi một sự cố nhà cung cấp đã biết làm đầy chuông; đặt lại sau đó.", "example": "Với mặc định 1 giờ, dùng dự phòng từ 10:00 tới 13:00 sẽ rung chuông lúc 10:00, 11:00, 12:00 và 13:00."}}},
{"key": "cis.ops.bell_every_daily_hours", "app": "cis", "area": "ops", "label": "Ops check: repeat a daily-scale bell after (hours)", "description": "The checks judged over a day write at most one admin bell per this many hours while they keep firing: a stage with no live model (llm_stage_coverage.<stage>), a fallback that raised a stage's cost (route_cost.<stage>) and replies cut at their ceiling (route_cut.<stage>). 24 hours was the S267 / S268 / S271 value.", "value_type": "int", "unit": "hours", "min_value": 1, "max_value": 168, "allowed_values": null, "default_value": 24, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How often the bell repeats a day-scale problem (no live model, fallback cost, cut replies).", "raise": "A known day-scale problem bells less often; it stays on the alerts catalogue meanwhile.", "lower": "The bell repeats within the day, though the numbers behind it change slowly.", "when": "Raise it while a known problem waits for a fix; lower it while a fix is watched.", "example": "With the default 24 hours, a stage with no live model since Monday 09:00 bells again on Tuesday 09:00."}, "vi": {"what": "Chuông lặp lại bao lâu một lần cho một vấn đề tính theo ngày (không có model sống, chi phí dự phòng, câu trả lời bị cắt).", "raise": "Một vấn đề theo ngày đã biết rung chuông thưa hơn; nó vẫn hiện trên danh mục cảnh báo.", "lower": "Chuông lặp lại trong ngày, dù số liệu phía sau thay đổi chậm.", "when": "Tăng khi một vấn đề đã biết đang chờ sửa; giảm khi đang theo dõi một bản sửa.", "example": "Với mặc định 24 giờ, một stage không có model sống từ 09:00 thứ Hai sẽ rung chuông lại lúc 09:00 thứ Ba."}}},
{"key": "cis.ops.bell_every_nightly_hours", "app": "cis", "area": "ops", "label": "Ops check: repeat a once-a-night bell after (hours)", "description": "The checks that run once a night write at most one admin bell per this many hours: the search demand research checks (research_stale_share and the four automatic research checks), the route digest and the quality funnel alerts (qf_*). It stays under 24 hours because the nightly run's start drifts, and a run a few hours earlier than the night before must still bell. 20 hours was the S268 / S271 value.", "value_type": "int", "unit": "hours", "min_value": 12, "max_value": 23, "allowed_values": null, "default_value": 20, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The minimum gap between two bells of a check that runs once a night.", "raise": "Up to 23 hours: a night run that starts a little earlier than the night before may not bell.", "lower": "Down to 12 hours: a second run on the same night (a manual re-run) may bell twice.", "when": "Keep the default; change it only if the nightly runs move a lot from night to night.", "example": "With the default 20 hours, runs at 02:10 and the next night at 01:30 both bell."}, "vi": {"what": "Khoảng cách tối thiểu giữa hai lần rung chuông của một kiểm tra chạy mỗi đêm một lần.", "raise": "Tối đa 23 giờ: một lượt chạy đêm bắt đầu sớm hơn đêm trước một chút có thể không rung chuông.", "lower": "Tối thiểu 12 giờ: một lượt chạy thứ hai trong cùng đêm (chạy lại bằng tay) có thể rung chuông hai lần.", "when": "Giữ mặc định; chỉ đổi khi giờ chạy đêm thay đổi nhiều giữa các đêm.", "example": "Với mặc định 20 giờ, lượt chạy lúc 02:10 và lượt đêm sau lúc 01:30 đều rung chuông."}}}
]
$seed$::jsonb) AS s (key text, app text, area text, label text, description text, value_type text, unit text,
                      min_value numeric, max_value numeric, allowed_values jsonb, default_value jsonb, scope_kind text,
                      impact text, approval text, evidence_required boolean, env_override text, cache_s integer,
                      enforced boolean, guide jsonb)
ON CONFLICT (key) DO NOTHING;
-- settings-seed:end

-- ── 2. The topic of an alert recipient ───────────────────────────────────────────────────────────────────────────

ALTER TABLE shared.alert_recipient ADD COLUMN IF NOT EXISTS topic text NOT NULL DEFAULT 'alerts';

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint
                    WHERE conname = 'alert_recipient_topic_chk' AND conrelid = 'shared.alert_recipient'::regclass) THEN
        ALTER TABLE shared.alert_recipient
            ADD CONSTRAINT alert_recipient_topic_chk CHECK (topic IN ('alerts', 'page'));
    END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS alert_recipient_active_topic_email_uq
    ON shared.alert_recipient (topic, email) WHERE status <> 'removed';
DROP INDEX IF EXISTS shared.alert_recipient_active_email_uq;

COMMENT ON COLUMN shared.alert_recipient.topic IS
    'AA-1171: alerts = the alerts SNS topic (every alert), page = the page-severity topic only';

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('469', now(), 'AA-1171: CIS in-app check thresholds and bell windows as settings (cis.ops.*) and alert_recipient.topic')
ON CONFLICT (version) DO NOTHING;

COMMIT;
